// packages/demo/src/utils/verifySignature.test.ts
// Cross-check the local verifier-signature recovery against a known historical
// proof generated by the live verifier on localhost:7047.
//
// Requires:
//   - verifier running at http://localhost:7047
//   - the sessionId below present in evidence.db (Phase 0 reference proof)
//   - verifier signer address = 0xa0ee7a142d267c1f36714e4a8f75612f20a79720
//     (derived from VERIFIER_PRIVATE_KEY=0x2a871d0798...09c6 in .env)

import { describe, expect, it } from 'vitest';
import { verifyVerifierSignature } from './verifySignature';
import type { ProofExportResponse } from './proof';

const REFERENCE_SID = '0006da30-2050-49a0-8d22-965e5f5c0daa';
const REFERENCE_SIGNER = '0xa0ee7a142d267c1f36714e4a8f75612f20a79720';

describe('verifyVerifierSignature', () => {
    it('recovers verifier address from known reference proof', async () => {
        const resp = await fetch(`http://localhost:7047/proof/${REFERENCE_SID}`, {
            headers: { Authorization: 'Bearer admin-demo-key' },
        });
        if (!resp.ok) {
            throw new Error(
                `Reference proof fetch failed (${resp.status}); ` +
                    `is verifier running and does evidence.db contain ${REFERENCE_SID}?`,
            );
        }
        const proof = (await resp.json()) as ProofExportResponse;

        const result = await verifyVerifierSignature(proof);

        expect(result.commitmentsHashMatch).toBe(true);
        expect(result.recovered.toLowerCase()).toBe(REFERENCE_SIGNER);
        expect(result.addressMatch).toBe(true);
    }, 15_000);
});
